"""Original Evo 2 report; independent of benchmarks published subsequently."""
def populate(c):
    base='https://static-content.springer.com/esm/art%3A10.1038%2Fs41586-026-10176-5/MediaObjects/41586_2026_10176_MOESM1_ESM.pdf'
    e=c.ev('evo-a3','evo-supp','Supplementary Methods A.3, prediction evaluations','Original Evo 2 methods distinguish likelihood evaluations, fitted embedding probes and DART subsets.',url=base+'#page=8')
    c.suite('evo-original','Evo 2 original-paper evaluations','Original Nature paper prediction, generation and mechanistic analyses. DART tasks are also linked to their own suite.',e,'evo',status='partial',notes='This is a source collection, not a benchmark with one shared split. Some exploratory analyses remain listed only in audit notes.')
    specs=[
      ('clinvar','ClinVar October 2024','Clinical pathogenicity','Expert-review ≥2-star pathogenic/likely pathogenic versus benign/likely benign variants; length ≤64 bp. Coding/noncoding, SNV/non-SNV, conservation and splice-proximity strata are linked variants.','binary classification','Expert clinical annotations',('variant-interpretation',),('variant-effects',),('genome',),('human',),'A.3.12–13',('auroc',)),
      ('splicevardb','SpliceVarDB','Splice disruption','Experimentally validated splice-altering versus non-altering human variants; exclude the low-frequency category.','binary classification','Experimental splice assays',('variant-interpretation','gene-therapy'),('variant-effects',),('splice',),('human',),'A.3.14',('auroc',)),
      ('brca1','Findlay et al. BRCA1 saturation genome editing','BRCA1 loss of function','Use experimental LOF versus functional labels; 249 intermediate variants are grouped with the functional category.','binary classification','Experimental saturation genome editing',('variant-interpretation',),('variant-effects',),('gene','exon','intron'),('human',),'A.3.15–16',('auroc',)),
      ('brca2','Huang et al. BRCA2 saturation genome editing','BRCA2 functional classification','Use the original experimental categories to distinguish deleterious from functional SNVs.','binary classification','Experimental saturation genome editing',('variant-interpretation',),('variant-effects',),('gene','exon','intron'),('human',),'A.3.15',('auroc',)),
      ('deg','DEG v16','Prokaryotic gene essentiality','Binary essential/nonessential labels across 56 bacterial and two archaeal genomes; compare sequence likelihood changes after gene-disrupting edits.','binary classification','Experimental essential-gene collections',('strain-engineering','microbial-genomics'),('variant-effects',),('gene','cds'),('bacteria','archaea'),'A.3.10',('auroc',)),
      ('phage-essential','Lambda and P1 experimental essentiality','Phage gene essentiality','Use published binary gene essentiality labels for lambda and P1; score gene-disrupting mutations in genomic context.','binary classification','Experimental gene essentiality',('microbial-genomics',),('variant-effects',),('gene','cds'),('phages',),'A.3.10',('auroc',)),
      ('depmap','DepMap CRISPR screens','Human gene essentiality','Average CRISPR essentiality across 1,401 cell lines; compare mutation-induced sequence-score changes to gene-level essentiality.','binary classification','Experimental CRISPR screen aggregation; class threshold requires further audit',('target-discovery',),('variant-effects',),('gene','cds'),('human',),'A.3.11',('auroc','auprc')),
      ('mrna-decay','Human metabolic RNA-labeling assay','mRNA decay rate','Average rates across measured cell lines; compare full-length or context-limited transcript likelihoods after a length-dependent LOESS correction.','regression / ranking','Experimental RNA turnover',('rna-engineering',),('functional-prediction',),('mrna',),('human',),'A.3.8',()),
    ]
    for slug,ds,target,desc,typ,labels,apps,caps,regions,pops,section,metrics in specs:
        ev=c.ev('evo-'+slug+'-methods','evo-supp',section,desc,url=base+'#page='+('14' if slug in ('clinvar','splicevardb','brca1','brca2') else '11'))
        t='evo-'+slug
        c.task(t,'evo-original',target,ds,target,desc,typ,labels,ev,applications=apps,capabilities=caps,regions=regions,populations=pops,input='Reference/alternate sequence or transcript as specified in the cited method',limitations='Exact released-file cohort and filtering have not yet been reconciled for this record.')
        p=c.protocol(t,t+'-zero','Original Evo 2 zero-shot scoring',ev,'zero-shot','Autoregressive sequence likelihood / reference–alternate difference','No downstream fitted classifier; label cohorts define evaluation. This does not establish that evaluated sequences were absent from genome pretraining.','variant / gene / transcript',metrics=metrics,embeddings=False,notes='ClinVar/BRCA use 8,192-bp variant-centered context. Essentiality uses gene disruption; mRNA decay uses transcript scores and a length correction.')
        c.use('evo2',t,ev,'evo',protocol=p)
    main=c.ev('evo-depmap-endpoint','evo-paper','Gene essentiality results and Extended Data Figure 3i','Human DepMap evaluation reports AUROC and AUPRC classification, although source CRISPR scores are averaged continuously over cell lines. The class threshold is not established by the inspected supplement passage.')
    c.field('tasks','evo-depmap','task_type',main)
    c.field('tasks','evo-depmap','label_basis',main)
    c.field('protocols','evo-depmap-zero','metrics',main)
    for t,n,unit in [('evo-brca1',3893,'SNVs'),('evo-deg',56,'bacterial genomes'),('evo-deg',2,'archaeal genomes'),('evo-depmap',16434,'protein-coding genes'),('evo-depmap',1401,'cell lines')]:c.count(t,n,unit,c.rows['tasks'][[r['id'] for r in c.rows['tasks']].index(t)]['evidence_id'])
    for name in ('coding','noncoding','SNV','non-SNV','near splice site','far from splice site','conservation strata'):
        c.variant('evo-clinvar','evo-clinvar-'+name.lower().replace(' ','-'),'ClinVar '+name,'evo-clinvar-methods',context='Consequence, allele length or genomic annotation stratum; not a separate dataset source.')
    ev='evo-brca1-methods'
    p=c.protocol('evo-brca1','evo-brca1-probe','Position-held-out BRCA1 probe',ev,'frozen probe','Reference and alternate embeddings; strand handling as in A.3.16','Split 1,326 positions into 1,060 train and 266 test; all alleles at a position stay together. Five-fold position-grouped CV within training selects hyperparameters.','genomic position',metrics=('auroc',),embeddings=True,fitted='Supervised classifier on model representations',selection='Training-only cross-validation; layer choices are recorded in the source.')
    c.use('evo2','evo-brca1',ev,'evo',protocol=p)
    for split,n in [('train',3104),('test',789)]:c.count('evo-brca1',n,'SNVs',ev,split=split,protocol=p)
    ev=c.ev('evo-exon-methods','evo-supp','A.3.9, Exon/intron classification','94-species collection with species partition and manually assigned human/mouse/zebrafish test species. Use linear or one-hidden-layer probes selected by validation.',url=base+'#page=12')
    t='evo-exon-intron'
    c.task(t,'evo-original','Exon versus intron positions','RefSeq GTF / 94-species collection','Exonic versus intronic position','Predict the annotation at the midpoint from bidirectional sequence representations. All exon annotations are retained without distinguishing constitutive and alternative exons.','binary classification','Reference gene annotations',ev,applications=('genome-annotation',),capabilities=('dense-annotation',),regions=('exon','intron'),populations=('animals','plants'),input='Two 8,192-bp strand-oriented contexts; combined span 16,383 bp',limitations='Species-held-out probe training does not imply those species were excluded from base-model pretraining. Two species were removed after initial partitioning.')
    p=c.protocol(t,t+'-probe','Species-partitioned position classifier',ev,'frozen probe','Concatenated forward/reverse position embeddings','Initial 80/10/10 species partition; human, mouse and zebrafish explicitly assigned to test. Final test panel has eight species.','species',metrics=('auroc',),embeddings=True,fitted='Linear classifier or one-hidden-layer MLP',selection='Architecture selected on validation species')
    c.use('evo2',t,ev,'evo',protocol=p)
    c.count(t,1500,'sampled positions per species',ev,qualifier='Final position-sampling protocol, not total across the collection.')
    for name,pop in [('Human','human'),('Mouse','mouse'),('Zebrafish','zebrafish'),('Barley','barley')]:c.variant(t,t+'-'+pop,name+' test species',ev)
    # Individually named DMS panels, preserving the original source rather than calling them RNAGym.
    efit=c.ev('evo-fitness-methods','evo-supp','A.3.6–7, Zero-shot protein/ncRNA fitness','Sequence likelihood versus experimental scores; absolute Spearman. The protein sets are selected collections, not all of ProteinGym.',url=base+'#page=11')
    bacterial=[('blat-firnberg','β-lactamase / Firnberg'),('blat-jacquier','β-lactamase / Jacquier'),('ccdb','CcdB'),('thermostability','Multiprotein thermostability'),('if1','IF-1'),('rnc','Rnc'),('haeiii','HaeIII'),('vim2','VIM-2'),('aph','APH(3′)II')]
    human=[('cbs','CBS'),('gdi1','GDI1'),('pde3a','PDE3A'),('p53-kotler','P53 / Kotler'),('p53-giacomelli','P53 / Giacomelli'),('brca1-dms','BRCA1 DMS')]
    ncrna=[('kobori','Kobori','ribozyme'),('andreasson','Andreasson','ribozyme'),('domingo','Domingo','trna'),('guy','Guy','trna'),('hayden','Hayden','ribozyme'),('pitt','Pitt','ribozyme'),('zhang','Zhang','rrna')]
    for pop,assays in [('bacteria',bacterial),('human',human)]:
        for slug,name in assays:
            t='evo-dms-'+slug
            c.task(t,'evo-original',name+': coding-variant fitness','Evo 2 selected DMS: '+name,'Experimental fitness','Use unique nucleotide sequences and nucleotide-level fitness from the original study; stop variants are included for nucleotide models but excluded for protein models.','regression / ranking','Experimental DMS',efit,applications=('protein-engineering',),capabilities=('variant-effects',),regions=('cds',),populations=(pop,),input='Full variant coding sequence',limitations='Assay-specific sequence counts and original data accession remain to be reconciled.')
            p=c.protocol(t,t+'-score','DMS likelihood ranking',efit,'zero-shot','Sequence likelihood; masked models use pseudolikelihood','No downstream fitting or supervised train/test partition; evaluate the retained assay variants.','variant / assay',metrics=('abs-spearman',),embeddings=False)
            c.use('evo2',t,efit,'evo',protocol=p)
    for slug,name,region in ncrna:
        t='evo-ncrna-'+slug
        c.task(t,'evo-original',name+': ncRNA fitness','Evo 2 selected ncRNA assay: '+name,'Experimental ncRNA fitness','Rank published ncRNA mutant sequences by model sequence score.','regression / ranking','Experimental mutagenesis',efit,applications=('rna-engineering',),capabilities=('variant-effects',),regions=('ncrna',region),populations=(),input='Mutant ncRNA sequence',limitations='Sequence origin and experimental host must be audited separately; an RNA family is not a taxonomic assignment.')
        p=c.protocol(t,t+'-score','ncRNA likelihood ranking',efit,'zero-shot','Sequence likelihood / pseudolikelihood','No fitted head; full retained assay scored.','mutant sequence',metrics=('abs-spearman',),embeddings=False)
        c.use('evo2',t,efit,'evo',protocol=p)
    c.finding(None,'A.3.6 calls the viral panel 18 DMS datasets, but its prose enumerates more entries and repeats an HIV-envelope author. Individual viral task identities require the released manifest; no exact viral task count is asserted here.',efit,severity='discrepancy',suite='evo-original')
    # Generation is scored by several diagnostics; do not manufacture a unified metric.
    egen=c.ev('evo-generation-methods','evo-supp','A.5, Unconstrained generation; A.6, Generative epigenomics','Gene completion, organelle/genome/chromosome sampling and predictor-guided regulatory design have distinct validation endpoints.',url=base+'#page=20')
    for slug,name,ds,pops,regions,desc in [
      ('completion','Gene completion','Evo 2 gene-completion panel',('bacteria','archaea','human','yeast','arabidopsis','chlamydomonas'),('cds',),'Prompt with 1 kb upstream and the first 500 or 1,000 bp of the gene, depending on species. Ten generations per prompt at temperature 0.7/top-k 4; align translated proteins and report percent protein recovery.'),
      ('mitochondria','Mitochondrial-genome generation','Human mitochondrial reference NC_012920.1',('human',),('genome','cds','trna','rrna'),'Prompt with 3,000 bp; generate ~16-kb sequences and assess gene content, synteny, homology, codon usage and predicted protein complexes.'),
      ('bacterial-genome','Bacterial-genome generation','Mycoplasma genitalium reference',('bacteria',),('genome','cds'),'Prompt with 10.5 kb; assess generated sequences using gene prediction, Pfam, homology and structure predictions.'),
      ('yeast-chr','Yeast-chromosome generation','Saccharomyces cerevisiae reference',('yeast',),('genome','cds'),'Generate extended chromosomal sequences and characterize predicted genes and homology.'),
      ('mouse-guidance','Guided mouse regulatory design','Evo 2 mouse generative-epigenomics experiments',('mouse',),('regulatory',),'Guide decoding with an external epigenomic predictor toward specified activity patterns; selected constructs undergo experimental validation.'),
      ('human-guidance','Guided human regulatory design','Evo 2 human generative-epigenomics experiments',('human',),('regulatory',),'Guide decoding using external sequence-to-function predictions and evaluate selected integrated constructs with ATAC-seq.'),
    ]:
        t='evo-gen-'+slug
        c.task(t,'evo-original',name,ds,'Generated-sequence properties / requested activity',desc,'generation / design','Computational annotations; experimental measurements for specified regulatory constructs',egen,applications=('regulatory-engineering','gene-therapy') if 'guidance' in slug else ('model-development',),capabilities=('generation','conditional-generation'),regions=regions,populations=pops,input='Natural sequence prefix; external predictor for guided designs',output='Generated sequence plus separate validation endpoints',limitations='Predicted genes, structures and synteny do not demonstrate viability of a generated genome. Detailed endpoint-specific task expansion and counts remain pending.')
        c.protocol(t,t+'-sampling','Original-paper sampling and validation',egen,'generation / inference-time guidance','Autoregressive decoding; guided variants also need an external activity predictor','Reference prompts and selected generated candidates; no universal train/test partition across these experiments.','prompt / generated construct',embeddings=False,notes='Consult A.5–6 for task-specific generation budgets, prompts and wet-lab endpoints.')
        c.use('evo2',t,egen,'evo')
    c.finding(None,'Likelihood perturbation diagnostics (start codons, genetic codes, codon ramps), sparse-autoencoder feature analyses and individual viral DMS tasks are registered in the original source but are not yet fully expanded here.',e,suite='evo-original')
